class Solution {
  public int longestSubarray(int[] nums, int k) {
    int n = nums.length, INF = Integer.MAX_VALUE;
    int[] e0 = new int[k], e1 = new int[k];
    java.util.Arrays.fill(e0, INF);
    java.util.Arrays.fill(e1, INF);
    int o0 = 0, o1 = 0, best = 0;
    for (int i = 0; i < n; i++) {
      int xm = ((nums[i] % k) + k) % k;
      // negate this element on top of a plain subarray ending at i - 1
      int shift = (((o0 - o1 - 2 * xm) % k) + k) % k;
      int newO0 = (o0 + xm) % k, newO1 = (o1 + xm) % k;
      for (int idx = 0; idx < k; idx++) {
        int start = e0[idx];
        if (start == INF) continue;
        int target = idx + shift;
        if (target >= k) target -= k;
        if (start < e1[target]) e1[target] = start;
      }
      o0 = newO0;
      o1 = newO1;
      int idxPlain = (((xm - o0) % k) + k) % k;
      if (i < e0[idxPlain]) e0[idxPlain] = i;
      int idxNeg = ((((k - xm) % k - o1) % k) + k) % k;
      if (i < e1[idxNeg]) e1[idxNeg] = i;
      int zero0 = ((-o0) % k + k) % k, zero1 = ((-o1) % k + k) % k;
      if (e0[zero0] != INF) best = Math.max(best, i - e0[zero0] + 1);
      if (e1[zero1] != INF) best = Math.max(best, i - e1[zero1] + 1);
    }
    return best;
  }
}
